#include <iostream>
#include <iomanip>
#include <cstdint>
#include <bitset>

int main() {
    // Sử dụng số nguyên không dấu 8-bit (uint8_t) để biểu diễn mẫu nhị phân như trong sách
    uint8_t a = 0b10101110; // 174 thập phân, 0xAE
    uint8_t b = 0b10010010; // 146 thập phân, 0x92

    std::cout << "a:         " << std::bitset<8>(a) << "\n";
    std::cout << "b:         " << std::bitset<8>(b) << "\n";
    std::cout << "a & b:     " << std::bitset<8>(a & b) << "\n";
    std::cout << "a | b:     " << std::bitset<8>(a | b) << "\n";
    std::cout << "a ^ b:     " << std::bitset<8>(a ^ b) << "\n";
    std::cout << "~a (8-bit):" << std::bitset<8>(static_cast<uint8_t>(~a)) << "\n";
    std::cout << "a << 2:    " << std::bitset<8>(static_cast<uint8_t>(a << 2)) << "\n";

    // Minh họa dịch phải 16-bit không dấu như ví dụ trong bảng
    uint16_t c = 0b1010111010101110; // 0xAEAE
    std::cout << "c >> 4:    " << std::bitset<16>(c >> 4) << "\n";

    // Minh họa toán tử gán thao tác bit
    uint8_t val = a;
    val ^= b;
    std::cout << "val ^= b:  " << std::bitset<8>(val) << "\n";

    return 0;
}
